html:
{% set pctx = doc._print_context or get_print_context(doc) %}
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <style>

    @page {
      size: A4;
      margin: 0;
    }

    * {
      box-sizing: border-box;
      font-family: Arial, sans-serif;
    }

    html,
    body {
      width: 100%;
      min-height: 100%;
      margin: 0;
      padding: 0;
      background: #fff;
    }

    /* =========================
       A4 PAGE
       ========================= */

    .page-container {
      position: relative;
      width: 100%;
      min-height: 297mm;
      background: #fff;
    }

    /* Reserve space for footer */
    .content-area {
      padding: 10px 20px 140px 20px;
    }

    .purple-text {
      color: #6b2d5c;
    }

    .bold {
      font-weight: bold;
    }

    .header-table,
    .info-table,
    .items-table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 20px;
    }

    /* =========================
       HEADER
       ========================= */

    .header-left {
      width: 40%;
      vertical-align: top;
      text-align: left;
      padding: 0;
    }

    .header-right {
      width: 60%;
      vertical-align: bottom;
      text-align: right;
    }

    .header-left img {
      max-height: 120px;
      width: auto;
      object-fit: contain;
      display: block;
      margin: 0;
      padding-right: 150px;
    }

    .doc-title {
      font-size: 32px;
      font-weight: bold;
      color: #6b2d5c;
      text-align: center;
      margin-bottom: 25px;
    }

    .info-title {
      font-size: 16px;
      font-weight: bold;
      color: #6b2d5c;
      margin-bottom: 8px;
    }

    /* =========================
       ITEMS TABLE
       ========================= */

    .items-table {
      width: 100%;
      border: 1.5px solid #000;
      margin-top: 10px;
      margin-bottom: 0;
      table-layout: fixed;
    }

    .items-table th,
    .items-table td {
      border: 1px solid #000;
      padding: 6px 8px;
      font-size: 12px;
      word-wrap: break-word;
      overflow-wrap: break-word;
    }

    .items-table th {
      background-color: #fff;
      color: #000;
      font-weight: bold;
      text-align: left;
    }

    /* =========================
       TOTALS
       ========================= */

    .totals-table {
      width: 35%;
      margin-left: auto;
      border-collapse: collapse;
      margin-top: 8px;
      margin-bottom: 20px;
    }

    .totals-table td {
      border: none;
      padding: 4px 8px;
      font-weight: bold;
      font-size: 12px;
    }

    /* =========================
       STAMP
       ========================= */

    .stamp-image {
      display: block;
      width: 220px;
      height: auto;
      margin: 8px 0 10px 0;
      object-fit: contain;
    }

    /* =========================
       PAYMENT TERMS
       ========================= */

    .payment-terms {
      margin-top: 15px;
      margin-bottom: 0;
      page-break-inside: avoid;
    }

    .payment-terms ul {
      list-style-type: disc;
      padding-left: 20px;
      margin-top: 8px;
      margin-bottom: 0;
      color: #6b2d5c;
      font-weight: bold;
      font-size: 14px;
    }

    .payment-terms li {
      margin-bottom: 6px;
    }

    /* =========================
       FOOTER
       ========================= */

    .company-footer-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      width: 100%;
      height: 117px;
      background-color: #b28fb8;
      color: #ffffff;
      text-align: center;
      padding: 24px 20px 20px 20px;
      border-top-left-radius: 16px;
      border-top-right-radius: 16px;
      font-size: 14px;
      font-weight: normal;
      line-height: 1.5;
      z-index: 9999;
      display: block;
    }

    /* =========================
       PRINT FIX
       ========================= */

    @media print {

      html,
      body {
        width: 100%;
        min-height: 100%;
        margin: 0;
        padding: 0;
        background: #fff !important;
      }

      .page-container {
        width: 100%;
        min-height: 297mm;
        background: #fff !important;
      }

      .content-area {
        padding: 10px 20px 140px 20px;
      }

      .items-table {
        width: 100%;
        table-layout: fixed;
      }

      .payment-terms {
        page-break-inside: avoid;
      }

      .company-footer-banner {
        position: fixed;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 117px;
        background-color: #b28fb8 !important;
      }

    }


  .section-row td { background: #f5f0f7; color: #6B1E64; }
  .subtotal-row td { border-top: 1px solid #6B1E64; }
  .purple-text { color: #6B1E64; }
  </style>
</head>
<body>
<div class="page-container">
  <div class="content-area">
<table class="header-table">
  <tr>
    <td class="header-left"><img src="/files/Alter .png" alt="Alter Space Logo"></td>
    <td class="header-right">
      <div><span class="purple-text bold">Ref.No:</span> <u>{{ doc.name }}</u></div>
      <div><span class="purple-text bold">Date:</span> <u>{{ doc.get_formatted("transaction_date") or '' }}</u></div>
      <div><span class="purple-text bold">Valid Till:</span> <u>{{ doc.get_formatted("valid_till") or '' }}</u></div>
    </td>
  </tr>
</table>
<div class="doc-title">Quotation</div>
<table class="info-table">
  <tr>
    <td style="width: 55%; vertical-align: top;">
      <div class="info-title">Client Information</div>
      <div><span class="purple-text bold">Company Name:</span> <u>{{ doc.customer_name or '' }}</u></div>
      <div><span class="purple-text bold">Contact Person:</span> <u>{{ doc.contact_person or doc.contact_display or '' }}</u></div>
      <div><span class="purple-text bold">Phone Number:</span> <u>{{ doc.contact_mobile or doc.contact_phone or doc.phone or '' }}</u></div>
    </td>
    <td style="width: 45%; vertical-align: top; text-align: right;">
      <div class="info-title">Event Details</div>
      {% if doc.get("title") %}<div><span class="purple-text bold">Event Name:</span> <u>{{ doc.title }}</u></div>{% endif %}
      {% if doc.get("event_date") %}<div><span class="purple-text bold">Event Date:</span> <u>{{ doc.get_formatted("event_date") }}</u></div>{% endif %}
      {% if doc.get("event_location") %}<div><span class="purple-text bold">Location:</span> <u>{{ doc.event_location }}</u></div>{% endif %}
      {% if doc.get("setup_date") %}<div><span class="purple-text bold">Setup Date:</span> <u>{{ doc.get_formatted("setup_date") }}</u></div>{% endif %}
    </td>
  </tr>
</table>
{% set ncols = 6 + (0 if pctx.hide_qty else 1) + (1 if pctx.show_days else 0) %}

<table class="items-table">
  <thead>
    <tr>
      <th style="width: 5%; text-align: center;">No</th>
      <th style="width: 20%;">Item Name</th>
      <th style="width: 25%;">Description</th>
      <th style="width: 10%;">UOM</th>
      {% if pctx.show_days %}<th style="width: 7%; text-align: center;">Days</th>{% endif %}
      {% if not pctx.hide_qty %}<th style="width: 7%; text-align: center;">Qty</th>{% endif %}
      <th style="width: 11%; text-align: right;">Unit Price</th>
      <th style="width: 12%; text-align: right;">Total Price</th>
    </tr>
  </thead>
  <tbody>
    {% set ns = namespace(counter=0) %}
    {% for row in doc.items %}
      {% if row.is_section or row.item_name == "Separator" or row.item_code == "Separator" %}
      <tr class="section-row">
        <td colspan="{{ ncols - 1 }}" style="text-align: left; font-weight: bold;">{{ row.section_title or row.description or row.item_name }}</td>
      </tr>
      {% elif row.is_section_subtotal %}
      <tr class="subtotal-row">
        <td colspan="{{ ncols - 2 }}" style="text-align: right;">Subtotal ({{ row.section_title or '' }}):</td>
        <td style="text-align: right; font-weight: bold;">{{ "{:,.2f}".format(row.amount or 0) }}</td>
      </tr>
      {% else %}
      {% set ns.counter = ns.counter + 1 %}
      <tr>
        <td style="text-align: center;">{{ ns.counter }}</td>
        <td>{{ row.item_name or row.item_code }}</td>
        <td>{{ row.description or '' }}</td>
        <td>{{ row.uom or '' }}</td>
        {% if pctx.show_days %}<td style="text-align: center;">{{ row.get("number_of_days") or row.get("custom_number_of_days") or row.get("no_of_days") or 1 }}</td>{% endif %}
        {% if not pctx.hide_qty %}<td style="text-align: center;">{{ row.get_formatted("qty", doc) }}</td>{% endif %}
        <td style="text-align: right;">{{ row.get_formatted("rate", doc) }}</td>
        <td style="text-align: right;">{{ row.get_formatted("amount", doc) }}</td>
      </tr>
      {% endif %}
    {% endfor %}
  </tbody>
</table>

{% set vat_amount = (doc.net_total or 0) * 0.15 %}
{% set grand_total = (doc.net_total or 0) if pctx.without_vat else (doc.net_total or 0) + vat_amount %}
<table style="width: 100%; border-collapse: collapse; margin-top: 8px; margin-bottom: 20px;">
  <tr>
    <td style="width: 60%; vertical-align: top;">
      {% if pctx.show_signature and doc.print_signature %}
      <img class="stamp-image" src="{{ frappe.db.get_value('Signature', doc.print_signature, 'attach') or '' }}" alt="Signature">
      {% else %}
      <img class="stamp-image" src="/files/Helina.png" alt="Company Stamp">
      {% endif %}
    </td>
    <td style="width: 40%; vertical-align: top;">
      <table class="totals-table" style="width: 100%; margin: 0;">
        <tr><td style="text-align: left;">Sub Total</td><td style="text-align: right;">{{ doc.get_formatted("net_total") }}</td></tr>
        {% if not pctx.without_vat %}
        <tr><td style="text-align: left;">Vat 15%</td><td style="text-align: right;">{{ frappe.utils.fmt_money(vat_amount, currency=doc.currency) }}</td></tr>
        {% endif %}
        <tr><td style="text-align: left;">Grand Total</td><td style="text-align: right;">{{ frappe.utils.fmt_money(grand_total, currency=doc.currency) }}</td></tr>
      </table>
    </td>
  </tr>
</table>

{% if pctx.show_payment_terms %}
<div class="payment-terms">
  <div class="info-title">Payment Terms</div>
  {% if doc.payment_schedule %}
  <table class="items-table">
    <thead><tr><th style="width: 8%;">No</th><th>Payment Term</th><th>Description</th><th style="text-align: right;">Amount</th></tr></thead>
    <tbody>
      {% for row in doc.payment_schedule %}
      <tr><td style="text-align: center;">{{ loop.index }}</td><td>{{ row.payment_term or '' }}</td><td>{{ row.description or '' }}</td><td style="text-align: right;">{{ "{:,.2f}".format(row.payment_amount or 0) }}</td></tr>
      {% endfor %}
    </tbody>
  </table>
  {% else %}
  <ul>
    <li>30% Booking confirmation</li>
    <li>50% Before Installation</li>
    <li>20% After Collection</li>
    <li>Security deposit if applicable</li>
  </ul>
  {% endif %}
</div>
{% endif %}
{% if pctx.show_terms and doc.terms %}
<div class="payment-terms">
  <div class="info-title">Terms &amp; Conditions</div>
  {{ doc.terms }}
</div>
{% endif %}

  </div>
  <div class="company-footer-banner">
<p style="font-size: 20px; font-weight: bold;">Thank you for your business.<br></p>
Wello Sefer Garad Mall 2nd floor, Addis Ababa, Ethiopia<br>
Phone: +251923060628, Email: helinamulatu@alter-decor.com
  </div>
</div>
</body>
</html>
